const $=s=>document.querySelector(s);const stored=(key,fallback)=>{try{return localStorage.getItem(key)||fallback}catch{return fallback}},storedList=key=>{try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value:[]}catch{return[]}};let language=['mn','en','ja'].includes(stored('nihongo-language','mn'))?stored('nihongo-language','mn'):'mn',level=['N5','N4','N3','N2','N1'].includes(stored('nihongo-level','N5'))?stored('nihongo-level','N5'):'N5',qi=0,answered=false,quizCorrect=0,savedOnly=false;
